import sys

def solve():
    s = sys.stdin.read().strip()
    if not s:
        print("true")
        return
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}
    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping:
            if not stack or stack[-1] != mapping[char]:
                print("false")
                return
            stack.pop()
    print("true" if len(stack) == 0 else "false")

if __name__ == '__main__':
    solve()

